import{f as e,c as t,o as r,ah as i}from"./chunks/framework.5bt9HFMa.js";const c=JSON.parse('{"title":"第六章 行为型设计模式","description":"详细介绍行为型设计模式，包括策略模式、观察者模式、命令模式等6种常用模式。","frontmatter":{"title":"第六章 行为型设计模式","date":"2025-11-19T00:00:00.000Z","description":"详细介绍行为型设计模式，包括策略模式、观察者模式、命令模式等6种常用模式。"},"headers":[],"relativePath":"series/软件设计体系结构/06-行为型设计模式.md","filePath":"series/软件设计体系结构/06-行为型设计模式.md","lastUpdated":1764042885000}'),o={name:"series/软件设计体系结构/06-行为型设计模式.md"};function l(s,a,n,h,p,_){return r(),t("div",null,a[0]||(a[0]=[i('<h1 id="第六章-行为型设计模式" tabindex="-1">第六章 行为型设计模式 <a class="header-anchor" href="#第六章-行为型设计模式" aria-label="Permalink to &quot;第六章 行为型设计模式&quot;">​</a></h1><p>行为型设计模式关注对象的行为和职责分配。</p><h2 id="_6-1-策略模式-strategy" tabindex="-1">6.1 策略模式（Strategy） <a class="header-anchor" href="#_6-1-策略模式-strategy" aria-label="Permalink to &quot;6.1 策略模式（Strategy）&quot;">​</a></h2><p>定义一系列算法，把它们一个个封装起来，并且使它们可相互替换。</p><p><strong>适用场景：</strong></p><ul><li>支持多种排序算法</li><li>支持多种支付方式</li></ul><h2 id="_6-2-观察者模式-observer" tabindex="-1">6.2 观察者模式（Observer） <a class="header-anchor" href="#_6-2-观察者模式-observer" aria-label="Permalink to &quot;6.2 观察者模式（Observer）&quot;">​</a></h2><p>定义对象间的一种一对多的依赖关系，当一个对象的状态发生改变时，所有依赖于它的对象都应该得到通知。</p><p><strong>应用：</strong></p><ul><li>事件监听系统</li><li>发布-订阅模式</li></ul><h2 id="_6-3-命令模式-command" tabindex="-1">6.3 命令模式（Command） <a class="header-anchor" href="#_6-3-命令模式-command" aria-label="Permalink to &quot;6.3 命令模式（Command）&quot;">​</a></h2><p>将请求封装为一个对象，从而可用不同的请求对客户进行参数化。</p><p><strong>优点：</strong></p><ul><li>降低系统耦合度</li><li>支持撤销和重做</li></ul><h2 id="_6-4-状态模式-state" tabindex="-1">6.4 状态模式（State） <a class="header-anchor" href="#_6-4-状态模式-state" aria-label="Permalink to &quot;6.4 状态模式（State）&quot;">​</a></h2><p>允许一个对象在其内部状态改变时改变它的行为。</p><p><strong>应用：</strong></p><ul><li>工作流状态管理</li><li>游戏状态管理</li></ul><h2 id="_6-5-职责链模式-chain-of-responsibility" tabindex="-1">6.5 职责链模式（Chain of Responsibility） <a class="header-anchor" href="#_6-5-职责链模式-chain-of-responsibility" aria-label="Permalink to &quot;6.5 职责链模式（Chain of Responsibility）&quot;">​</a></h2><p>为了避免请求发送者与多个请求处理者耦合在一起，将这些处理者连成一条链，并沿着这条链传递请求，直到有处理者处理它为止。</p><h2 id="_6-6-备忘录模式-memento" tabindex="-1">6.6 备忘录模式（Memento） <a class="header-anchor" href="#_6-6-备忘录模式-memento" aria-label="Permalink to &quot;6.6 备忘录模式（Memento）&quot;">​</a></h2><p>在不破坏封装性的前提下，捕获一个对象的内部状态，并在该对象之外保存这个状态。</p><p><strong>应用：</strong></p><ul><li>撤销功能</li><li>快照保存</li></ul><hr><p>更多内容敬请期待...</p>',26)]))}const m=e(o,[["render",l]]);export{c as __pageData,m as default};
